/* 모든 h1 요소에 스타일 적용 */
h1 {
  color: #333;
  font-size: 2rem;
  margin-bottom: 1rem;
}

/* .card 클래스를 가진 요소에 박스 스타일 */
.card {
  padding: 20px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background-color: white;
}

/* 768px 이하 화면에서 다른 레이아웃 */
@media (max-width: 768px) {
  .card {
    padding: 10px;
  }
}
